import collections,json,pathlib,sys
p=pathlib.Path(sys.argv[1]); d=json.loads(p.read_text()); rows=d['records']
c=[r for r in rows if r['status']=='COMPARED_VERIFIED']
r=[r for r in c if r['reference'] is not None]
def rate(rows,k):
 e=sum(x[k]['errors'] for x in rows); n=sum(x[k]['reference_units'] for x in rows)
 return {'errors':e,'reference_units':n,'CER':e/n if n else None}
s={'status':d['status'],'source':d['source'],'build':d['build'],'helper_sha256':d['helper_sha256'],'wall_seconds':d['wall_seconds'],'expected':len(d['prepared_cases']),'recorded':len(rows),'statuses':dict(collections.Counter(x['status'] for x in rows)),'verified_comparisons':len(c),'exact_equal':sum(x['exact_text_equal'] for x in c),'normalized_equal':sum(x['normalized_text_equal'] for x in c),'preview':rate(r,'preview_reference_CER'),'scalar':rate(r,'scalar_reference_CER'),'preview_decode_seconds_total':sum(x['preview_decode_seconds'] for x in c),'scalar_decode_seconds_total':sum(x['scalar_decode_seconds'] for x in c),'differences':[{'id':x['id'],'frames':x['frames'],'raw':x['raw_differences'],'normalized':x['normalized_differences'],'preview_CER':x['preview_reference_CER'],'scalar_CER':x['scalar_reference_CER']} for x in c if not x['exact_text_equal']],'no_accepted_prefix':[{'id':x['id'],'status':x['status']} for x in rows if x['status']=='COMPARED_NO_ACCEPTED_PREFIX'],'not_comparable':[{'id':x['id'],'status':x['status'],'reason':x.get('reason')} for x in rows if x['status']=='NOT_COMPARABLE'],'all_full_reference_preview':rate([x for x in rows if x.get('preview_reference_CER') is not None],'preview_reference_CER'),'all_full_reference_scalar':rate([x for x in rows if x.get('scalar_reference_CER') is not None],'scalar_reference_CER'),'scope':'Direct signed-worker controlled endpoints. This does not measure native original-rate latency. The 30.0 s prefix has no partial reference; excluded from CER.'}
out=p.with_name('summary.json');out.write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n');print(json.dumps(s,ensure_ascii=False,indent=2))
